/**
 * Translates any text into the target language while strictly preserving all numbers,
 * digits (0-9), currency symbols (₹), percentages (%), and tech acronyms!
 */
export function translatePreservingNumbers(text: string, lang: Language): string {
  if (!text) return text;
  if (lang === 'hi' && /[ऀ-ॿ]/.test(text)) return text;
  if (lang === 'en' && !/[ऀ-ॿ]/.test(text)) return text;

  // 1. Extract and protect numbers & currency expressions
  const numberTokens: string[] = [];
  const tokenized = text.replace(/([₹Rs\.]*\s*\d+(?:[,\.]\d+)*(?:\s*(?:%|kg|g|gm|ml|ltr|pkt|bag|pc))?)/gi, (match) => {
    const idx = numberTokens.length;
    numberTokens.push(match);
    return `__NUM_${idx}__`;
  });

  // 2. Look up known phrases in target language
  let result = tokenized;
  const vocab = VOCABULARY_MAP[lang] || VOCABULARY_MAP.hi;
  
  // Hindi to target language common word mappings
  const hindiToEnglishWords: Record<string, string> = {
    'ग्राहक': 'Customer', 'कुल': 'Total', 'नकद': 'Cash', 'बाकी': 'Due', 'छूट': 'Discount',
    'बिक्री': 'Sale', 'खरीद': 'Purchase', 'पर्ची': 'Bill', 'बिल': 'Invoice', 'तारीख': 'Date',
    'स्टॉक': 'Stock', 'गोदाम': 'Godown', 'दुकान': 'Shop', 'टैक्स': 'Tax', 'दर': 'Rate',
    'भाव': 'Price', 'मुनाफा': 'Profit', 'खर्च': 'Expense', 'फ़ोन': 'Phone', 'नाम': 'Name',
    'सुरक्षित करें': 'Save', 'रद्द करें': 'Cancel', 'पूर्ण': 'Done', 'हटाएं': 'Delete',
    'शेयर': 'Share', 'प्रिंट': 'Print', 'आज': 'Today', 'उधार': 'Due', 'भुगतान': 'Paid',
    'नमस्ते': 'Namaste', 'सफल': 'Success', 'जोड़ें': 'Add', 'खोजें': 'Search', 'वापस': 'Back'
  };

  // Replace each mapped word
  for (const [hindiWord, englishKey] of Object.entries(hindiToEnglishWords)) {
    if (result.includes(hindiWord)) {
      const targetWord = vocab[englishKey] || (lang === 'en' ? englishKey : hindiWord);
      result = result.split(hindiWord).join(targetWord);
    }
  }

  // 3. Restore protected numbers
  numberTokens.forEach((num, idx) => {
    result = result.split(`__NUM_${idx}__`).join(num);
  });

  return result;
}
